# Generates src/compiler/json_runtime.kark from runtime/json/c/*.
#
# v1.2.20: the self-hosted compiler embeds the C23 JSON DOM runtime as
# emitLine one-liners (the same style as the OS metrics/TLS runtimes), because
# Karkain has no file-embedding builtin. This script is the single
# implementation of that transform - never hand-edit the generated file.
# Rerun after touching runtime/json/c/*:
#   powershell -ExecutionPolicy Bypass -File scripts\gen-json-runtime.ps1
#
# A Go freshness gate (pkg/codegen TestJSONKarkFresh) compares the recorded
# SHA-256 digests with the live sources and fails when they drift.

$ErrorActionPreference = "Stop"
$root = Split-Path -Parent $PSScriptRoot
$srcDir = Join-Path $root "runtime/json/c"
$outPath = Join-Path $root "src/compiler/json_runtime.kark"

$files = @("karkain_json.h", "karkain_json.c")

function Escape-KarkString([string]$s) {
    return $s.Replace("\", "\\").Replace('"', '\"')
}

$sb = New-Object System.Text.StringBuilder
[void]$sb.AppendLine("// Generated by scripts/gen-json-runtime.ps1 - DO NOT EDIT BY HAND.")
[void]$sb.AppendLine("// v1.2.20: C23 JSON DOM runtime embedded for the self-hosted")
[void]$sb.AppendLine("// backend. Regenerate with: powershell -File scripts/gen-json-runtime.ps1")
$digests = @()
foreach ($f in $files) {
    $bytes = [System.IO.File]::ReadAllBytes((Join-Path $srcDir $f))
    $norm = $bytes | Where-Object { $_ -ne 13 }
    $sha = [System.Security.Cryptography.SHA256]::Create()
    $hex = ($sha.ComputeHash($norm) | ForEach-Object { $_.ToString("x2") }) -join ""
    $digests += "$f=$hex"
}
[void]$sb.AppendLine("// runtime-sha256: " + ($digests -join " "))
[void]$sb.AppendLine("")
[void]$sb.AppendLine("// emitJSONRuntime appends the C23 JSON runtime (header + implementation,")
[void]$sb.AppendLine("// self-include stripped exactly like the Go backend).")
[void]$sb.AppendLine("func emitJSONRuntime(state) {")

foreach ($f in $files) {
    [void]$sb.AppendLine('    emitLine(state, "// ==== v1.2.20 runtime source: ' + $f + ' ====")')
    $text = [System.IO.File]::ReadAllText((Join-Path $srcDir $f), [System.Text.Encoding]::UTF8)
    foreach ($line in $text -split '\r?\n') {
        $t = $line.Trim()
        if ($t.StartsWith('#include "karkain_json.h"')) { continue }
        [void]$sb.AppendLine('    emitLine(state, "' + (Escape-KarkString $line) + '")')
    }
}
[void]$sb.AppendLine("}")

$final = $sb.ToString() -replace '\r(?=\n)', ''
[System.IO.File]::WriteAllText($outPath, $final, (New-Object System.Text.UTF8Encoding $false))
Write-Host "wrote $outPath"
